insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary) values
('Мединский курс (Том 3)','1','الإِعْرَابُ وَالْبِنَاءُ (Склоняемые и неизменяемые слова)','<p><strong>Суть правила.</strong> В арабском языке изменяемое слово меняет окончание в зависимости от роли в предложении, а неизменяемое сохраняет одну форму. Важно сначала определить: перед нами имя, глагол или частица, а затем искать признак падежа или неизменяемости.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">جَاءَ الطَّالِبُ</strong> — Пришёл студент..</li><li><strong dir="rtl" lang="ar">رَأَيْتُ الطَّالِبَ</strong> — Я увидел студента..</li><li><strong dir="rtl" lang="ar">سَلَّمْتُ عَلَى الطَّالِبِ</strong> — Я поприветствовал студента..</li></ol>','1','rule','В арабском языке изменяемое слово меняет окончание в зависимости от роли в предложении, а неизменяемое сохраняет одну форму. Важно сначала определить: перед нами имя, глагол или частица, а затем искать признак падежа или неизменяемости.'),
('Мединский курс (Том 3)','2','عَلَامَاتُ الإِعْرَابِ (Основные и второстепенные падежные показатели)','<p><strong>Суть правила.</strong> Для обычного единственного имени обычно работают дамма, фатха и касра. У двойственного числа, правильного множественного числа и пяти имён появляются второстепенные показатели: алиф, йа или вав. Сначала определите тип слова, потом выбирайте окончание.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">المُسْلِمُونَ حَاضِرُونَ</strong> — Мусульмане присутствуют..</li><li><strong dir="rtl" lang="ar">رَأَيْتُ المُسْلِمِينَ</strong> — Я увидел мусульман..</li><li><strong dir="rtl" lang="ar">مَرَرْتُ بِالمُسْلِمِينَ</strong> — Я прошёл мимо мусульман..</li></ol>','1','rule','Для обычного единственного имени обычно работают дамма, фатха и касра. У двойственного числа, правильного множественного числа и пяти имён появляются второстепенные показатели: алиф, йа или вав. Сначала определите тип слова, потом выбирайте окончание.'),
('Мединский курс (Том 3)','3','الإِعْرَابُ التَّقْدِيرِيُّ (Скрытое падежное окончание)','<p><strong>Суть правила.</strong> У некоторых слов падежное окончание не видно на письме или в произношении, но грамматическая роль от этого не исчезает. Это бывает, например, у имён на алиф маκсура и у части имён на йа. Падеж определяется по месту слова в предложении.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">جَاءَ الفَتَى</strong> — Пришёл юноша..</li><li><strong dir="rtl" lang="ar">رَأَيْتُ الفَتَى</strong> — Я увидел юношу..</li><li><strong dir="rtl" lang="ar">مَرَرْتُ بِالفَتَى</strong> — Я прошёл мимо юноши..</li></ol>','1','rule','У некоторых слов падежное окончание не видно на письме или в произношении, но грамматическая роль от этого не исчезает. Это бывает, например, у имён на алиф маκсура и у части имён на йа. Падеж определяется по месту слова в предложении.'),
('Мединский курс (Том 3)','4','الاِسْمُ المَقْصُورُ وَالمَنْقُوصُ (Имена на алиф маκсура и на йа)','<p><strong>Суть правила.</strong> Имя на алиф маκсура оканчивается на ى, а недостаточное имя обычно оканчивается на йа перед которой касра. В неопределённом состоянии у недостаточного имени йа в именительном и родительном падежах часто не пишется и заменяется танвином.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">هَذَا قَاضٍ عَادِلٌ</strong> — Это справедливый судья..</li><li><strong dir="rtl" lang="ar">سَلَّمْتُ عَلَى قَاضٍ</strong> — Я поприветствовал судью..</li><li><strong dir="rtl" lang="ar">رَأَيْتُ قَاضِيًا عَادِلًا</strong> — Я увидел справедливого судью..</li></ol>','1','rule','Имя на алиф маκсура оканчивается на ى, а недостаточное имя обычно оканчивается на йа перед которой касра. В неопределённом состоянии у недостаточного имени йа в именительном и родительном падежах часто не пишется и заменяется танвином.'),
('Мединский курс (Том 3)','5','المَمْنُوعُ مِنَ الصَّرْفِ (Несклоняемое на танвин имя)','<p><strong>Суть правила.</strong> Некоторые имена не принимают танвин и в родительном падеже без артикля и идафы получают фатху вместо касры. Это часто относится к определённым моделям, некоторым именам собственным и словам на -ان. Если появляется ال или идафа, касра возвращается.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">جَاءَ أَحْمَدُ</strong> — Пришёл Ахмад..</li><li><strong dir="rtl" lang="ar">رَأَيْتُ أَحْمَدَ</strong> — Я увидел Ахмада..</li><li><strong dir="rtl" lang="ar">مَرَرْتُ بِأَحْمَدَ</strong> — Я прошёл мимо Ахмада..</li></ol>','1','rule','Некоторые имена не принимают танвин и в родительном падеже без артикля и идафы получают фатху вместо касры. Это часто относится к определённым моделям, некоторым именам собственным и словам на -ان. Если появляется ال или идафа, касра возвращается.'),
('Мединский курс (Том 3)','6','وَاوُ الحَالِ (Вав обстоятельства)','<p><strong>Суть правила.</strong> Вав обстоятельства соединяет основное действие с ситуацией, в которой оно происходит. После неё часто идёт именное предложение с местоимением, относящимся к участнику главного действия. По-русски обычно передаётся «в то время как», «когда».</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">جَاءَ الطَّالِبُ وَهُوَ ضَاحِكٌ</strong> — Студент пришёл, улыбаясь..</li><li><strong dir="rtl" lang="ar">دَخَلْتُ وَالمُدَرِّسُ جَالِسٌ</strong> — Я вошёл, когда преподаватель сидел..</li><li><strong dir="rtl" lang="ar">خَرَجَ وَهُوَ مُسْرِعٌ</strong> — Он вышел, торопясь..</li></ol>','1','rule','Вав обстоятельства соединяет основное действие с ситуацией, в которой оно происходит. После неё часто идёт именное предложение с местоимением, относящимся к участнику главного действия. По-русски обычно передаётся «в то время как», «когда».'),
('Мединский курс (Том 3)','7','اِسْمُ الفِعْلِ (Имя действия)','<p><strong>Суть правила.</strong> Имя действия по значению действует как глагол, но само не спрягается. Оно может выражать приказ, прошлое действие или настоящее состояние. Его нужно запоминать как готовую формулу вместе со значением и управлением.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">صَهْ عَنِ الكَلَامِ</strong> — Тише, прекрати разговор..</li><li><strong dir="rtl" lang="ar">آمِينَ بَعْدَ الدُّعَاءِ</strong> — Аминь после мольбы..</li><li><strong dir="rtl" lang="ar">هَيْهَاتَ مَا تُوعَدُونَ</strong> — Далеко то, что вам обещают..</li></ol>','1','rule','Имя действия по значению действует как глагол, но само не спрягается. Оно может выражать приказ, прошлое действие или настоящее состояние. Его нужно запоминать как готовую формулу вместе со значением и управлением.'),
('Мединский курс (Том 3)','8','النَّعْتُ الحَقِيقِيُّ وَالسَّبَبِيُّ (Прямое и причинное определение)','<p><strong>Суть правила.</strong> Прямое определение согласуется с определяемым словом в роде, числе, определённости и падеже. Причинное определение описывает связанный с ним предмет и после него обычно стоит явное существительное. Сначала найдите, что именно характеризует прилагательное.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">جَاءَ طَالِبٌ مُجْتَهِدٌ</strong> — Пришёл прилежный студент..</li><li><strong dir="rtl" lang="ar">رَأَيْتُ طَالِبًا مُجْتَهِدًا</strong> — Я увидел прилежного студента..</li><li><strong dir="rtl" lang="ar">جَاءَ رَجُلٌ حَسَنٌ خُلُقُهُ</strong> — Пришёл человек с хорошим нравом..</li></ol>','1','rule','Прямое определение согласуется с определяемым словом в роде, числе, определённости и падеже. Причинное определение описывает связанный с ним предмет и после него обычно стоит явное существительное. Сначала найдите, что именно характеризует прилагательное.'),
('Мединский курс (Том 3)','9','الإِضَافَةُ وَحَذْفُ النُّونِ (Идафа и удаление нуна)','<p><strong>Суть правила.</strong> В идафе первое слово связано со вторым и получает падеж по своей роли. У двойственного числа и правильного мужского множественного при идафе удаляется нун: كِتَابَا الطَّالِبِ, مُسْلِمُو البَلَدِ. Второе слово стоит в родительном падеже.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">هَذَا كِتَابُ الطَّالِبِ</strong> — Это книга студента..</li><li><strong dir="rtl" lang="ar">جَاءَ مُسْلِمُو البَلَدِ</strong> — Пришли мусульмане страны..</li><li><strong dir="rtl" lang="ar">رَأَيْتُ كِتَابَيْ الطَّالِبِ</strong> — Я увидел две книги студента..</li></ol>','1','rule','В идафе первое слово связано со вторым и получает падеж по своей роли. У двойственного числа и правильного мужского множественного при идафе удаляется нун: كِتَابَا الطَّالِبِ, مُسْلِمُو البَلَدِ. Второе слово стоит в родительном падеже.'),
('Мединский курс (Том 3)','10','كِلَا وَكِلْتَا (Оба и обе)','<p><strong>Суть правила.</strong> Кِلَا и كِلْتَا в идафе перед явным существительным ведут себя как обычные имена двойственного числа: в именительном падеже алиф, в винительном и родительном — йа. С местоимениями употребляются формы كِلَاهُمَا и كِلْتَاهُمَا.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">جَاءَ كِلَا الطَّالِبَيْنِ</strong> — Пришли оба студента..</li><li><strong dir="rtl" lang="ar">رَأَيْتُ كِلَا الطَّالِبَيْنِ</strong> — Я увидел обоих студентов..</li><li><strong dir="rtl" lang="ar">كِلْتَا البِنْتَيْنِ مُجْتَهِدَتَانِ</strong> — Обе девушки прилежны..</li></ol>','1','rule','Кِلَا и كِلْتَا в идафе перед явным существительным ведут себя как обычные имена двойственного числа: в именительном падеже алиф, в винительном и родительном — йа. С местоимениями употребляются формы كِلَاهُمَا и كِلْتَاهُمَا.'),
('Мединский курс (Том 3)','11','المَصْدَرُ المُؤَوَّلُ (Развёрнутый масдар)','<p><strong>Суть правила.</strong> Сочетание أَنْ с глаголом настоящего времени может занимать место масдара: أُرِيدُ أَنْ أَتَعَلَّمَ — «я хочу учиться». Такое сочетание можно мысленно заменить существительным «обучение», «приход», «чтение». Это помогает увидеть роль оборота в предложении.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">أُرِيدُ أَنْ أَتَعَلَّمَ</strong> — Я хочу учиться..</li><li><strong dir="rtl" lang="ar">سَرَّنِي أَنْ جِئْتَ</strong> — Меня обрадовало, что ты пришёл..</li><li><strong dir="rtl" lang="ar">يُمْكِنُ أَنْ نَبْدَأَ الآنَ</strong> — Мы можем начать сейчас..</li></ol>','1','rule','Сочетание أَنْ с глаголом настоящего времени может занимать место масдара: أُرِيدُ أَنْ أَتَعَلَّمَ — «я хочу учиться». Такое сочетание можно мысленно заменить существительным «обучение», «приход», «чтение». Это помогает увидеть роль оборота в предложении.'),
('Мединский курс (Том 3)','12','المُبْتَدَأُ وَالخَبَرُ (Подлежащее и сказуемое)','<p><strong>Суть правила.</strong> Именное предложение обычно начинается с мубтада — того, о ком говорится, затем идёт хабар — то, что о нём сообщается. Оба слова обычно находятся в именительном падеже. Хабар может быть одним словом, предложением или предложной конструкцией.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">العِلْمُ نَافِعٌ</strong> — Знание полезно..</li><li><strong dir="rtl" lang="ar">الطَّالِبُ فِي الفَصْلِ</strong> — Студент в классе..</li><li><strong dir="rtl" lang="ar">أَبِي مُدَرِّسٌ</strong> — Мой отец преподаватель..</li></ol>','1','rule','Именное предложение обычно начинается с мубтада — того, о ком говорится, затем идёт хабар — то, что о нём сообщается. Оба слова обычно находятся в именительном падеже. Хабар может быть одним словом, предложением или предложной конструкцией.'),
('Мединский курс (Том 3)','13','المَفْعُولُ فِيهِ (Обстоятельство времени и места)','<p><strong>Суть правила.</strong> Маф‘уль фихи называет время или место, в пределах которого произошло действие. Обычно это винительный падеж, но предлог меняет конструкцию: فِي البَيْتِ — «в доме». Не путайте его с дополнением: он отвечает на «когда?» или «где?».</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">سَافَرْتُ لَيْلًا</strong> — Я путешествовал ночью..</li><li><strong dir="rtl" lang="ar">جَلَسْتُ أَمَامَ المُدَرِّسِ</strong> — Я сел перед преподавателем..</li><li><strong dir="rtl" lang="ar">دَرَسْتُ يَوْمَ الجُمُعَةِ</strong> — Я учился в пятницу..</li></ol>','1','rule','Маф‘уль фихи называет время или место, в пределах которого произошло действие. Обычно это винительный падеж, но предлог меняет конструкцию: فِي البَيْتِ — «в доме». Не путайте его с дополнением: он отвечает на «когда?» или «где?».'),
('Мединский курс (Том 3)','14','لَامُ الأَمْرِ (Лам приказа)','<p><strong>Суть правила.</strong> Лам приказа ставится перед глаголом настоящего времени и делает его в усечённом состоянии: لِيَكْتُبْ. Она часто переводится «пусть». Важно отличать её от лама цели, после которого глагол обычно стоит в винительном состоянии.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">لِيَكْتُبْ الطَّالِبُ الدَّرْسَ</strong> — Пусть студент запишет урок..</li><li><strong dir="rtl" lang="ar">لِنَذْهَبْ إِلَى المَكْتَبَةِ</strong> — Пойдём в библиотеку..</li><li><strong dir="rtl" lang="ar">فَلْيَقُلْ خَيْرًا</strong> — Пусть говорит доброе..</li></ol>','1','rule','Лам приказа ставится перед глаголом настоящего времени и делает его в усечённом состоянии: لِيَكْتُبْ. Она часто переводится «пусть». Важно отличать её от лама цели, после которого глагол обычно стоит в винительном состоянии.'),
('Мединский курс (Том 3)','15','أَدَوَاتُ الشَّرْطِ الجَازِمَةُ (Условные частицы, которые усекaют)','<p><strong>Суть правила.</strong> После условной частицы جازمة обычно два глагола настоящего времени получают усечение: глагол условия и ответ условия. Самые частые частицы: إِنْ, مَنْ, مَا, مَهْمَا. Сначала найдите условие, затем его результат.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">إِنْ تَجْتَهِدْ تَنْجَحْ</strong> — Если будешь стараться, преуспеешь..</li><li><strong dir="rtl" lang="ar">مَنْ يَصْدُقْ يُحْتَرَمْ</strong> — Кто говорит правду, того уважают..</li><li><strong dir="rtl" lang="ar">مَهْمَا تَفْعَلْ تُجْزَ بِهِ</strong> — Что бы ты ни сделал, за это получишь воздаяние..</li></ol>','1','rule','После условной частицы جازمة обычно два глагола настоящего времени получают усечение: глагол условия и ответ условия. Самые частые частицы: إِنْ, مَنْ, مَا, مَهْمَا. Сначала найдите условие, затем его результат.'),
('Мединский курс (Том 3)','16','جَمْعُ التَّكْسِيرِ (Ломаное множественное число)','<p><strong>Суть правила.</strong> Ломаное множественное число меняет внутреннюю структуру слова, поэтому его нельзя всегда вывести по одному правилу. Его лучше учить вместе с единственным числом: كِتَاب — كُتُب, رَجُل — رِجَال. В таблице словаря такие пары должны стоять в одной строке.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">هَذِهِ كُتُبٌ نَافِعَةٌ</strong> — Это полезные книги..</li><li><strong dir="rtl" lang="ar">رَأَيْتُ رِجَالًا فِي الطَّرِيقِ</strong> — Я увидел мужчин на дороге..</li><li><strong dir="rtl" lang="ar">لِلْمَسَاجِدِ أَبْوَابٌ</strong> — У мечетей есть двери..</li></ol>','1','rule','Ломаное множественное число меняет внутреннюю структуру слова, поэтому его нельзя всегда вывести по одному правилу. Его лучше учить вместе с единственным числом: كِتَاب — كُتُب, رَجُل — رِجَال. В таблице словаря такие пары должны стоять в одной строке.'),
('Мединский курс (Том 3)','17','الفِعْلُ الرُّبَاعِيُّ وَالمَزِيدُ (Четырёхбуквенный и расширенный глагол)','<p><strong>Суть правила.</strong> У четырёхбуквенного глагола четыре коренные буквы, например دَحْرَجَ. Расширенные глаголы строятся по моделям и дают дополнительные оттенки смысла. При разборе сначала определите основу и модель, а затем ищите производные: масдар, действительное и страдательное причастие.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">دَحْرَجَ الوَلَدُ الكُرَةَ</strong> — Мальчик покатил мяч..</li><li><strong dir="rtl" lang="ar">تَدَحْرَجَتِ الكُرَةُ</strong> — Мяч покатился..</li><li><strong dir="rtl" lang="ar">اِسْتَخْرَجَ الطَّالِبُ الفَائِدَةَ</strong> — Студент извлёк пользу..</li></ol>','1','rule','У четырёхбуквенного глагола четыре коренные буквы, например دَحْرَجَ. Расширенные глаголы строятся по моделям и дают дополнительные оттенки смысла. При разборе сначала определите основу и модель, а затем ищите производные: масдар, действительное и страдательное причастие.'),
('Мединский курс (Том 4)','1','الفِعْلُ المُتَعَدِّي وَاللَّازِمُ (Переходный и непереходный глагол)','<p><strong>Суть правила.</strong> Переходный глагол требует прямого дополнения без предлога: كَتَبَ الدَّرْسَ. Непереходный глагол описывает действие, которое не переходит прямо на объект: ذَهَبَ الطَّالِبُ. У одного глагола управление может меняться с предлогом.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">كَتَبَ الطَّالِبُ الدَّرْسَ</strong> — Студент написал урок..</li><li><strong dir="rtl" lang="ar">ذَهَبَ الطَّالِبُ إِلَى المَكْتَبَةِ</strong> — Студент пошёл в библиотеку..</li><li><strong dir="rtl" lang="ar">جَلَسَ المُدَرِّسُ فِي الفَصْلِ</strong> — Преподаватель сел в классе..</li></ol>','1','rule','Переходный глагол требует прямого дополнения без предлога: كَتَبَ الدَّرْسَ. Непереходный глагол описывает действие, которое не переходит прямо на объект: ذَهَبَ الطَّالِبُ. У одного глагола управление может меняться с предлогом.'),
('Мединский курс (Том 4)','2','البَابُ الثَّالِثُ: فَاعَلَ (Третья порода: взаимность или направленное действие)','<p><strong>Суть правила.</strong> Модель فَاعَلَ часто выражает участие двух сторон или направленное действие по отношению к кому-то: شَارَكَ, سَاعَدَ, قَاتَلَ. Но точное значение всегда проверяется по словарю. Настоящее время обычно строится по модели يُفَاعِلُ.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">شَارَكَ الطَّالِبُ فِي المُسَابَقَةِ</strong> — Студент участвовал в соревновании..</li><li><strong dir="rtl" lang="ar">سَاعَدَ الأَبُ ابْنَهُ</strong> — Отец помог сыну..</li><li><strong dir="rtl" lang="ar">قَابَلْتُ صَدِيقِي أَمْسِ</strong> — Я встретил друга вчера..</li></ol>','1','rule','Модель فَاعَلَ часто выражает участие двух сторон или направленное действие по отношению к кому-то: شَارَكَ, سَاعَدَ, قَاتَلَ. Но точное значение всегда проверяется по словарю. Настоящее время обычно строится по модели يُفَاعِلُ.'),
('Мединский курс (Том 4)','3','البَابُ الخَامِسُ: تَفَعَّلَ (Пятая порода: действие над собой)','<p><strong>Суть правила.</strong> Модель تَفَعَّلَ часто передаёт усвоение, постепенное изменение или действие, которое человек совершает над собой: تَعَلَّمَ, تَجَمَّلَ. В настоящем времени она обычно выглядит как يَتَفَعَّلُ. Шадда в середине модели важна.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">تَعَلَّمَ الوَلَدُ العَرَبِيَّةَ</strong> — Мальчик изучал арабский язык..</li><li><strong dir="rtl" lang="ar">تَجَمَّلَ الرَّجُلُ لِلصَّلَاةِ</strong> — Мужчина привёл себя в порядок для молитвы..</li><li><strong dir="rtl" lang="ar">تَذَكَّرْتُ الدَّرْسَ</strong> — Я вспомнил урок..</li></ol>','1','rule','Модель تَفَعَّلَ часто передаёт усвоение, постепенное изменение или действие, которое человек совершает над собой: تَعَلَّمَ, تَجَمَّلَ. В настоящем времени она обычно выглядит как يَتَفَعَّلُ. Шадда в середине модели важна.'),
('Мединский курс (Том 4)','4','البَابُ السَّادِسُ: تَفَاعَلَ (Шестая порода: взаимность)','<p><strong>Суть правила.</strong> Модель تَفَاعَلَ часто показывает взаимное действие нескольких участников: تَعَاوَنَ, تَرَاسَلَ, تَشَاوَرَ. У модели есть начальное تَ и долгий алиф после второй коренной буквы. Смысл взаимности нужно видеть по контексту.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">تَعَاوَنَ الطُّلَّابُ فِي العَمَلِ</strong> — Студенты сотрудничали в работе..</li><li><strong dir="rtl" lang="ar">تَشَاوَرَ الرَّجُلَانِ</strong> — Двое мужчин посоветовались..</li><li><strong dir="rtl" lang="ar">تَرَاسَلَ الصَّدِيقَانِ</strong> — Два друга переписывались..</li></ol>','1','rule','Модель تَفَاعَلَ часто показывает взаимное действие нескольких участников: تَعَاوَنَ, تَرَاسَلَ, تَشَاوَرَ. У модели есть начальное تَ и долгий алиф после второй коренной буквы. Смысл взаимности нужно видеть по контексту.'),
('Мединский курс (Том 4)','5','البَابُ السَّابِعُ: اِنْفَعَلَ (Седьмая порода: изменение состояния)','<p><strong>Суть правила.</strong> Модель اِنْفَعَلَ часто обозначает действие, происшедшее с предметом или изменение его состояния: اِنْكَسَرَ, اِنْفَتَحَ. Нередко она соответствует непереходному значению. Начальное اِنْ — часть модели, а не отдельный предлог.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">اِنْكَسَرَ الزُّجَاجُ</strong> — Стекло разбилось..</li><li><strong dir="rtl" lang="ar">اِنْفَتَحَ البَابُ</strong> — Дверь открылась..</li><li><strong dir="rtl" lang="ar">اِنْقَطَعَ الحَبْلُ</strong> — Верёвка порвалась..</li></ol>','1','rule','Модель اِنْفَعَلَ часто обозначает действие, происшедшее с предметом или изменение его состояния: اِنْكَسَرَ, اِنْفَتَحَ. Нередко она соответствует непереходному значению. Начальное اِنْ — часть модели, а не отдельный предлог.'),
('Мединский курс (Том 4)','6','البَابُ الثَّامِنُ: اِفْتَعَلَ (Восьмая порода: усилие и приобретение)','<p><strong>Суть правила.</strong> Модель اِفْتَعَلَ имеет добавочный ت после первой коренной буквы. Она встречается в глаголах усилия, приобретения, принятия действия и в других значениях: اِجْتَهَدَ, اِشْتَرَى, اِجْتَمَعَ. Некоторые согласные влияют на произношение ت.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">اِجْتَهَدَ الطَّالِبُ فِي دَرْسِهِ</strong> — Студент усердно занимался..</li><li><strong dir="rtl" lang="ar">اِشْتَرَيْتُ كِتَابًا</strong> — Я купил книгу..</li><li><strong dir="rtl" lang="ar">اِجْتَمَعَ النَّاسُ فِي المَسْجِدِ</strong> — Люди собрались в мечети..</li></ol>','1','rule','Модель اِفْتَعَلَ имеет добавочный ت после первой коренной буквы. Она встречается в глаголах усилия, приобретения, принятия действия и в других значениях: اِجْتَهَدَ, اِشْتَرَى, اِجْتَمَعَ. Некоторые согласные влияют на произношение ت.'),
('Мединский курс (Том 4)','7','البَابُ التَّاسِعُ: اِفْعَلَّ (Девятая порода: цвет и физическое свойство)','<p><strong>Суть правила.</strong> Модель اِفْعَلَّ редка и чаще всего выражает цвет или сильное физическое свойство: اِحْمَرَّ, اِسْوَدَّ. У неё удвоенная последняя коренная буква. Её не следует смешивать с обычной восьмой породой.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">اِحْمَرَّ الوَجْهُ</strong> — Лицо покраснело..</li><li><strong dir="rtl" lang="ar">اِسْوَدَّ اللَّيْلُ</strong> — Ночь почернела..</li><li><strong dir="rtl" lang="ar">اِصْفَرَّ الوَرَقُ</strong> — Лист пожелтел..</li></ol>','1','rule','Модель اِفْعَلَّ редка и чаще всего выражает цвет или сильное физическое свойство: اِحْمَرَّ, اِسْوَدَّ. У неё удвоенная последняя коренная буква. Её не следует смешивать с обычной восьмой породой.'),
('Мединский курс (Том 4)','8','البَابُ العَاشِرُ: اِسْتَفْعَلَ (Десятая порода: просьба и поиск)','<p><strong>Суть правила.</strong> Модель اِسْتَفْعَلَ часто выражает просьбу, поиск или стремление получить что-либо: اِسْتَغْفَرَ, اِسْتَخْرَجَ, اِسْتَعْمَلَ. Начальное اِسْتَ — часть модели. Значение конкретного глагола всё равно проверяется по словарю.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">اِسْتَغْفَرَ المُسْلِمُ رَبَّهُ</strong> — Мусульманин попросил прощения у Господа..</li><li><strong dir="rtl" lang="ar">اِسْتَخْرَجَ الطَّالِبُ الفَائِدَةَ</strong> — Студент извлёк пользу..</li><li><strong dir="rtl" lang="ar">اِسْتَعْمَلْتُ القَلَمَ</strong> — Я использовал ручку..</li></ol>','1','rule','Модель اِسْتَفْعَلَ часто выражает просьбу, поиск или стремление получить что-либо: اِسْتَغْفَرَ, اِسْتَخْرَجَ, اِسْتَعْمَلَ. Начальное اِسْتَ — часть модели. Значение конкретного глагола всё равно проверяется по словарю.'),
('Мединский курс (Том 4)','9','الفِعْلُ الرُّبَاعِيُّ (Четырёхбуквенные глаголы)','<p><strong>Суть правила.</strong> В четырёхбуквенном корне четыре основные буквы. Основная модель прошлого времени — فَعْلَلَ, а настоящего — يُفَعْلِلُ. У неё есть свои производные модели, поэтому не нужно насильно разбирать её как трёхбуквенный глагол.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">دَحْرَجَ الوَلَدُ الكُرَةَ</strong> — Мальчик покатил мяч..</li><li><strong dir="rtl" lang="ar">وَسْوَسَ الشَّيْطَانُ</strong> — Шайтан нашёптывал..</li><li><strong dir="rtl" lang="ar">زَلْزَلَ الزِّلْزَالُ الأَرْضَ</strong> — Землетрясение сотрясло землю..</li></ol>','1','rule','В четырёхбуквенном корне четыре основные буквы. Основная модель прошлого времени — فَعْلَلَ, а настоящего — يُفَعْلِلُ. У неё есть свои производные модели, поэтому не нужно насильно разбирать её как трёхбуквенный глагол.'),
('Мединский курс (Том 4)','10','ضَمَائِرُ النَّصْبِ المُنْفَصِلَةُ وَالمُتَّصِلَةُ (Отдельные и слитные объектные местоимения)','<p><strong>Суть правила.</strong> Отдельные формы إِيَّايَ, إِيَّاكَ, إِيَّاهُ употребляются для усиления или после особых конструкций. Слитные окончания присоединяются к глаголу, предлогу или имени: رَأَيْتُهُ, لَهُ, كِتَابُهُ. Выбирайте форму по лицу, числу и роду.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">إِيَّاكَ نَعْبُدُ</strong> — Тебе одному мы поклоняемся..</li><li><strong dir="rtl" lang="ar">رَأَيْتُهُ فِي السُّوقِ</strong> — Я увидел его на рынке..</li><li><strong dir="rtl" lang="ar">أَعْطَيْتُهَا كِتَابًا</strong> — Я дал ей книгу..</li></ol>','1','rule','Отдельные формы إِيَّايَ, إِيَّاكَ, إِيَّاهُ употребляются для усиления или после особых конструкций. Слитные окончания присоединяются к глаголу, предлогу или имени: رَأَيْتُهُ, لَهُ, كِتَابُهُ. Выбирайте форму по лицу, числу и роду.'),
('Мединский курс (Том 4)','11','المَفْعُولُ المُطْلَقُ (Абсолютное дополнение)','<p><strong>Суть правила.</strong> Маф‘уль мутлак — масдар того же глагола, который усиливает действие, указывает число раз или вид действия. Он обычно стоит в винительном падеже. Сравните: جَلَسْتُ جُلُوسًا — «я действительно сел / я сидел».</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">شَكَرْتُهُ شُكْرًا</strong> — Я искренне поблагодарил его..</li><li><strong dir="rtl" lang="ar">ضَرَبْتُهُ ضَرْبَتَيْنِ</strong> — Я ударил его два раза..</li><li><strong dir="rtl" lang="ar">جَلَسْتُ جُلُوسَ المُؤَدَّبِ</strong> — Я сел как воспитанный человек..</li></ol>','1','rule','Маф‘уль мутлак — масдар того же глагола, который усиливает действие, указывает число раз или вид действия. Он обычно стоит в винительном падеже. Сравните: جَلَسْتُ جُلُوسًا — «я действительно сел / я сидел».'),
('Мединский курс (Том 4)','12','المَفْعُولُ لِأَجْلِهِ (Дополнение причины)','<p><strong>Суть правила.</strong> Маф‘уль ли-аджлихи называет внутреннюю причину действия: страх, надежду, уважение. Обычно это неопределённый масдар в винительном падеже, а субъект и время совпадают с основным действием. Его часто можно перевести «из-за», «ради», «по причине».</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">دَرَسْتُ رَغْبَةً فِي العِلْمِ</strong> — Я учился из стремления к знанию..</li><li><strong dir="rtl" lang="ar">وَقَفْتُ اِحْتِرَامًا لِلْمُعَلِّمِ</strong> — Я встал из уважения к учителю..</li><li><strong dir="rtl" lang="ar">تَصَدَّقْتُ طَلَبًا لِلْأَجْرِ</strong> — Я подал милостыню ради награды..</li></ol>','1','rule','Маф‘уль ли-аджлихи называет внутреннюю причину действия: страх, надежду, уважение. Обычно это неопределённый масдар в винительном падеже, а субъект и время совпадают с основным действием. Его часто можно перевести «из-за», «ради», «по причине».'),
('Мединский курс (Том 4)','13','التَّمْيِيزُ (Уточняющее слово)','<p><strong>Суть правила.</strong> Тамйиз снимает неясность после количества, меры, веса или сравнительной степени. Часто он неопределённый и стоит в винительном падеже; после чисел 100 и 1000 обычно бывает родительный единственного числа. Спросите себя: какое слово нуждается в уточнении?</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">اِشْتَرَيْتُ عِشْرِينَ كِتَابًا</strong> — Я купил двадцать книг..</li><li><strong dir="rtl" lang="ar">مُحَمَّدٌ أَكْثَرُ عِلْمًا</strong> — Мухаммад более знающий..</li><li><strong dir="rtl" lang="ar">عِنْدِي لِتْرٌ مَاءً</strong> — У меня литр воды..</li></ol>','1','rule','Тамйиз снимает неясность после количества, меры, веса или сравнительной степени. Часто он неопределённый и стоит в винительном падеже; после чисел 100 и 1000 обычно бывает родительный единственного числа. Спросите себя: какое слово нуждается в уточнении?'),
('Мединский курс (Том 4)','14','الحَالُ (Обстоятельство состояния)','<p><strong>Суть правила.</strong> Халь описывает временное состояние участника действия в момент действия. Обычно это неопределённое слово в винительном падеже и его можно перевести деепричастием или оборотом «будучи». Не путайте с постоянным определением: халь временный.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">جَاءَ الطَّالِبُ مُبْتَسِمًا</strong> — Студент пришёл улыбаясь..</li><li><strong dir="rtl" lang="ar">دَخَلَ الوَلَدُ بَاكِيًا</strong> — Мальчик вошёл плача..</li><li><strong dir="rtl" lang="ar">رَجَعَ المُسَافِرُ مُتْعَبًا</strong> — Путник вернулся уставшим..</li></ol>','1','rule','Халь описывает временное состояние участника действия в момент действия. Обычно это неопределённое слово в винительном падеже и его можно перевести деепричастием или оборотом «будучи». Не путайте с постоянным определением: халь временный.'),
('Мединский курс (Том 4)','15','الاِسْتِثْنَاءُ (Исключение)','<p><strong>Суть правила.</strong> Исключение с إِلَّا отделяет то, что не входит в общую группу. Форма слова после إِلَّا зависит от того, полное ли предложение, есть ли отрицание и упомянуто ли исключаемое. Начинайте разбор с основной группы, затем выделяйте исключение.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">جَاءَ الطُّلَّابُ إِلَّا خَالِدًا</strong> — Пришли студенты, кроме Халида..</li><li><strong dir="rtl" lang="ar">مَا جَاءَ أَحَدٌ إِلَّا خَالِدٌ</strong> — Никто не пришёл, кроме Халида..</li><li><strong dir="rtl" lang="ar">قَرَأْتُ الكُتُبَ إِلَّا كِتَابًا</strong> — Я прочитал книги, кроме одной книги..</li></ol>','1','rule','Исключение с إِلَّا отделяет то, что не входит в общую группу. Форма слова после إِلَّا зависит от того, полное ли предложение, есть ли отрицание и упомянуто ли исключаемое. Начинайте разбор с основной группы, затем выделяйте исключение.'),
('Мединский курс (Том 4)','16','نُونُ التَّوْكِيدِ (Нун усиления)','<p><strong>Суть правила.</strong> Нун усиления присоединяется к глаголу для сильного подчёркивания: لَأَكْتُبَنَّ. Бывает тяжёлая نَّ и лёгкая نْ. Она влияет на форму глагола, поэтому её нельзя принимать за обычное окончание множественного числа.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">وَاللَّهِ لَأَجْتَهِدَنَّ</strong> — Клянусь Аллахом, я непременно буду стараться..</li><li><strong dir="rtl" lang="ar">لَيَكْتُبَنَّ الطَّالِبُ</strong> — Студент непременно напишет..</li><li><strong dir="rtl" lang="ar">لَا تَكْذِبَنَّ</strong> — Ни в коем случае не лги..</li></ol>','1','rule','Нун усиления присоединяется к глаголу для сильного подчёркивания: لَأَكْتُبَنَّ. Бывает тяжёлая نَّ и лёгкая نْ. Она влияет на форму глагола, поэтому её нельзя принимать за обычное окончание множественного числа.'),
('Мединский курс (Том 4)','17','المَمْنُوعُ مِنَ الصَّرْفِ (Несклоняемые на танвин формы)','<p><strong>Суть правила.</strong> Несклоняемые на танвин имена не получают танвин и без ال/идафы имеют фатху в родительном падеже. В четвёртом томе это правило закрепляется на новых моделях и именах. Всегда проверяйте, есть ли у слова артикль или идафа: от этого зависит касра.</p><p><strong>Как применять.</strong> Найдите конструкцию в предложении, определите её роль, затем проверьте окончание и смысл по контексту.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">صَلَّيْتُ فِي مَسَاجِدَ كَثِيرَةٍ</strong> — Я молился во многих мечетях..</li><li><strong dir="rtl" lang="ar">مَرَرْتُ بِأَحْمَدَ</strong> — Я прошёл мимо Ахмада..</li><li><strong dir="rtl" lang="ar">صَلَّيْتُ فِي المَسَاجِدِ الكَبِيرَةِ</strong> — Я молился в больших мечетях..</li></ol>','1','rule','Несклоняемые на танвин имена не получают танвин и без ال/идафы имеют фатху в родительном падеже. В четвёртом томе это правило закрепляется на новых моделях и именах. Всегда проверяйте, есть ли у слова артикль или идафа: от этого зависит касра.');
